package com.triathlon.prep.core;
import java.io.*;import java.util.*;import java.util.zip.*;
/** Independent versioned manual ledger, atomic and idempotent by mode/batch/bib. */
public final class FileManualRecordStore implements ManualRecordStore {
 public static final int MAX_RECORDS=1000;private static final int MAGIC=0x4d504331;private final File file,pending,backup;
 public FileManualRecordStore(File directory)throws IOException{if(directory==null||(!directory.exists()&&!directory.mkdirs())||!directory.isDirectory())throw new IOException("Private manual ledger unavailable");file=new File(directory,"manual.bin");pending=new File(directory,"manual.bin.new");backup=new File(directory,"manual.bin.bak");}
 public synchronized List<ManualRecord> list()throws IOException{recover();List<ManualRecord> rows=new ArrayList<>();if(!file.exists())return rows;if(!file.isFile()||file.length()>512*1024)throw new IOException("Invalid manual ledger");CRC32 crc=new CRC32();try(DataInputStream in=new DataInputStream(new CheckedInputStream(new FileInputStream(file),crc))){if(in.readInt()!=MAGIC||in.readInt()!=1)throw new IOException("Unknown manual ledger");int count=in.readInt();if(count<0||count>MAX_RECORDS)throw new IOException("Invalid manual count");Set<String> ids=new HashSet<>(),keys=new HashSet<>();for(int i=0;i<count;i++){ManualRecord r=new ManualRecord(in.readUTF(),in.readLong(),Verification.Mode.valueOf(in.readUTF()),in.readUTF(),in.readUTF());if(!ids.add(r.id)||!keys.add(r.key()))throw new IOException("Duplicate manual result");rows.add(r);}long actual=crc.getValue();if(in.readLong()!=actual||in.read()!=-1)throw new IOException("Manual ledger checksum failed");return rows;}catch(IllegalArgumentException e){throw new IOException("Invalid manual ledger",e);}}
 public synchronized ManualRecord commit(ManualRecord proposed)throws IOException{if(proposed==null)throw new IOException("Manual result required");List<ManualRecord> rows=list();for(ManualRecord row:rows){if(row.key().equals(proposed.key()))return row;if(row.id.equals(proposed.id))throw new IOException("Manual ID collision");}if(rows.size()>=MAX_RECORDS)throw new IOException("Manual ledger capacity reached");rows.add(proposed);CRC32 crc=new CRC32();try(FileOutputStream stream=new FileOutputStream(pending);DataOutputStream out=new DataOutputStream(new CheckedOutputStream(stream,crc))){out.writeInt(MAGIC);out.writeInt(1);out.writeInt(rows.size());for(ManualRecord row:rows){out.writeUTF(row.id);out.writeLong(row.timestamp);out.writeUTF(row.mode.name());out.writeUTF(row.rosterBatchId);out.writeUTF(row.rosterBib);}out.writeLong(crc.getValue());out.flush();stream.getFD().sync();}if(file.exists()&&!file.renameTo(backup))throw new IOException("Cannot preserve manual ledger");if(!pending.renameTo(file)){if(backup.exists()&&!backup.renameTo(file))throw new IOException("Manual restore failed");throw new IOException("Manual replace failed");}if(backup.exists()&&!backup.delete())throw new IOException("Manual commit cleanup failed");return proposed;}
 private void recover()throws IOException{if(backup.exists()){if(file.exists()&&!file.delete())throw new IOException("Manual recovery failed");if(!backup.renameTo(file))throw new IOException("Manual restore failed");}if(pending.exists()&&!pending.delete())throw new IOException("Cannot discard interrupted manual write");}
}
